// Flexible test bot for probing the Halite environment protocol.
// Behaviour controlled entirely by environment variables.
//
//  NAME        : string to print as the name (default "TB"). Interpreted with
//                simple escapes: \n \t \0 \\ ; use RAWNAME to skip escapes.
//  NONAME      : if set, never print a name at all.
//  NAMEEOF     : if set, print the name then close stdout and exit(0).
//  NAMEEOFNOCR : if set, print the name WITHOUT a trailing newline then exit.
//  INITSLEEP   : ms to sleep before printing the name.
//  TURNSLEEP   : ms to sleep each turn before responding.
//  SLEEPTURN   : only sleep on this 1-based turn (default: every turn).
//  MOVES       : string printed every turn (default "").
//  MOVESTURN   : turn (1-based) on which to print MOVES; other turns print "".
//  DIETURN     : after responding to this turn, exit(0) (closing stdout).
//  DIETURNPRE  : upon receiving this turn's map, exit(0) without responding.
//  ABORTTURN   : upon receiving this turn's map, abort() (SIGABRT).
//  ERRTURN     : write ERRMSG to stderr on this turn (default turn 1).
//  ERRMSG      : text for stderr.
//  ERRINIT     : if set, write ERRMSG to stderr during init.
//  NOREAD      : if set, never read stdin at all (just print name, loop).
//  EATSTDIN    : if set, read/print but never flush (test buffering).
//  LOGFILE     : append a trace of what was read/when to this file.
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>

static double now_ms(void) {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec * 1000.0 + ts.tv_nsec / 1e6;
}
static void msleep(long ms) {
    if (ms <= 0) return;
    struct timespec ts; ts.tv_sec = ms / 1000; ts.tv_nsec = (ms % 1000) * 1000000L;
    nanosleep(&ts, NULL);
}
static const char *E(const char *k, const char *d) { char *v = getenv(k); return v ? v : d; }
static long EI(const char *k, long d) { char *v = getenv(k); return v ? atol(v) : d; }

static FILE *lg = NULL;
static double t0;
static void trace(const char *fmt, ...) {
    if (!lg) return;
    va_list ap; va_start(ap, fmt);
    fprintf(lg, "[%8.1f] ", now_ms() - t0);
    vfprintf(lg, fmt, ap);
    fputc('\n', lg);
    fflush(lg);
    va_end(ap);
}

// unescape into out, return length
static size_t unesc(const char *s, char *out) {
    size_t o = 0;
    for (size_t i = 0; s[i]; i++) {
        if (s[i] == '\\' && s[i+1]) {
            i++;
            switch (s[i]) {
                case 'n': out[o++] = '\n'; break;
                case 'r': out[o++] = '\r'; break;
                case 't': out[o++] = '\t'; break;
                case '0': out[o++] = '\0'; break;
                case 's': out[o++] = ' '; break;
                case '\\': out[o++] = '\\'; break;
                default: out[o++] = s[i];
            }
        } else out[o++] = s[i];
    }
    return o;
}

static char linebuf[1 << 22];

int main(void) {
    t0 = now_ms();
    const char *lf = getenv("LOGFILE");
    if (lf) lg = fopen(lf, "a");
    trace("start pid=%d", (int)getpid());

    if (getenv("ERRINIT")) { fprintf(stderr, "%s", E("ERRMSG", "stderr-init\n")); fflush(stderr); }

    if (!getenv("NOREAD")) {
        for (int i = 0; i < 3; i++) {
            if (!fgets(linebuf, sizeof linebuf, stdin)) { trace("init read %d EOF", i); return 3; }
            trace("init line %d len=%zu head=%.40s", i, strlen(linebuf), linebuf);
        }
    }
    msleep(EI("INITSLEEP", 0));

    if (!getenv("NONAME")) {
        char *nm = malloc(1 << 22);
        size_t n = unesc(E("NAME", "TB"), nm);
        fwrite(nm, 1, n, stdout);
        if (!getenv("NAMEEOFNOCR")) fputc('\n', stdout);
        fflush(stdout);
        trace("sent name len=%zu", n);
    }
    if (getenv("NAMEEOF") || getenv("NAMEEOFNOCR")) { trace("exiting after name"); return 0; }

    long turn = 0;
    long sleepturn = EI("SLEEPTURN", -1);
    long turnsleep = EI("TURNSLEEP", 0);
    long dieturn = EI("DIETURN", -1);
    long dieturnpre = EI("DIETURNPRE", -1);
    long abortturn = EI("ABORTTURN", -1);
    long errturn = EI("ERRTURN", -1);
    long movesturn = EI("MOVESTURN", -1);
    const char *moves = E("MOVES", "");

    for (;;) {
        if (getenv("NOREAD")) { msleep(100000); continue; }
        if (!fgets(linebuf, sizeof linebuf, stdin)) { trace("turn read EOF at turn %ld", turn + 1); break; }
        turn++;
        trace("got frame turn=%ld len=%zu", turn, strlen(linebuf));
        if (turn == dieturnpre) { trace("exit pre-response"); return 0; }
        if (turn == abortturn) { trace("abort"); abort(); }
        if (turn == errturn) { fprintf(stderr, "%s", E("ERRMSG", "stderr-turn\n")); fflush(stderr); }
        if (sleepturn < 0 || turn == sleepturn) msleep(turnsleep);
        char *mv = malloc(1 << 22);
        size_t n = 0;
        if (movesturn < 0 || turn == movesturn) n = unesc(moves, mv);
        fwrite(mv, 1, n, stdout);
        fputc('\n', stdout);
        fflush(stdout);
        free(mv);
        trace("sent moves turn=%ld len=%zu", turn, n);
        if (turn == dieturn) { trace("exit after response"); return 0; }
    }
    trace("clean exit, saw %ld turns", turn);
    return 0;
}

import subprocess, os, json, glob, shutil, sys, time, tempfile

EXE = "/workspace/executable"

def run(cmds, seed=1, w=5, h=5, extra=None, timeout=400, quiet=True, cwd=None, keep=False):
    d = cwd or tempfile.mkdtemp(dir="/tmp/pt/runs")
    os.makedirs(d, exist_ok=True)
    args = [EXE, "-d", "%d %d" % (w, h), "-s", str(seed)]
    if quiet: args.append("-q")
    if extra: args += extra
    args += list(cmds)
    t0 = time.time()
    try:
        r = subprocess.run(args, capture_output=True, cwd=d, timeout=timeout)
        out, err, rc = r.stdout, r.stderr, r.returncode
    except subprocess.TimeoutExpired as e:
        out, err, rc = (e.stdout or b""), (e.stderr or b""), "TIMEOUT"
    el = time.time() - t0
    reps = sorted(glob.glob(os.path.join(d, "*.hlt")))
    rep = json.load(open(reps[-1])) if reps else None
    logs = {}
    for f in sorted(glob.glob(os.path.join(d, "*.log"))):
        logs[os.path.basename(f)] = open(f, "rb").read()
    res = dict(stdout=out, stderr=err, rc=rc, rep=rep, logs=logs, elapsed=el, dir=d, args=args)
    if not keep: shutil.rmtree(d, ignore_errors=True)
    return res

def bot(**kw):
    """build an 'env K=V ... /tmp/pt/tbot' command string"""
    parts = ["env"] + ["%s=%s" % (k, v) for k, v in kw.items()] + ["/tmp/pt/tbot"]
    return " ".join(parts)

def summarize(res, showrep=True):
    print("args:", res["args"])
    print("rc:", res["rc"], "elapsed: %.3f" % res["elapsed"])
    print("--- stdout ---"); print(res["stdout"].decode(errors="replace"))
    print("--- stderr ---"); print(res["stderr"].decode(errors="replace"))
    for k, v in res["logs"].items():
        print("--- log", k, "len", len(v), "---")
        print(repr(v))
    if showrep and res["rep"]:
        rp = res["rep"]
        print("rep: nf=%s np=%s names=%s wh=%sx%s" % (rp["num_frames"], rp["num_players"], rp["player_names"], rp["width"], rp["height"]))

