// Raw protocol recorder: logs every read() from stdin with timestamps and exact bytes.
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>

static double t0;
static double now_ms(void){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec*1000.0+ts.tv_nsec/1e6; }

int main(void){
    t0 = now_ms();
    FILE *lg = fopen(getenv("RAWLOG") ? getenv("RAWLOG") : "/tmp/pt/raw.txt", "w");
    setvbuf(lg, NULL, _IONBF, 0);
    const char *name = getenv("NAME") ? getenv("NAME") : "RAW";
    long nlines_before_name = getenv("NLINES") ? atol(getenv("NLINES")) : 3;
    long maxturns = getenv("MAXTURNS") ? atol(getenv("MAXTURNS")) : 5;

    char buf[1<<20];
    long lines = 0, turns = 0;
    int sent_name = 0;
    for (;;) {
        ssize_t n = read(0, buf, sizeof buf);
        fprintf(lg, "[%8.1f] read() -> %zd\n", now_ms()-t0, n);
        if (n <= 0) { fprintf(lg, "EOF/err\n"); break; }
        fprintf(lg, "  BYTES(%zd): <<<", n);
        fwrite(buf, 1, n, lg);
        fprintf(lg, ">>>\n");
        // count newlines
        long nl = 0; for (ssize_t i=0;i<n;i++) if (buf[i]=='\n') nl++;
        fprintf(lg, "  newlines=%ld  lastbyte=%d\n", nl, (int)(unsigned char)buf[n-1]);
        lines += nl;
        if (!sent_name && lines >= nlines_before_name) {
            printf("%s\n", name); fflush(stdout);
            fprintf(lg, "[%8.1f] sent name\n", now_ms()-t0);
            sent_name = 1;
            continue;
        }
        if (sent_name) {
            turns++;
            printf("\n"); fflush(stdout);
            fprintf(lg, "[%8.1f] sent empty moves (turn %ld)\n", now_ms()-t0, turns);
            if (turns >= maxturns) { fprintf(lg,"stopping responses, still reading\n"); }
        }
    }
    fprintf(lg, "[%8.1f] exit\n", now_ms()-t0);
    return 0;
}

// Signal-observing bot: records which signals it receives, to see how the env
// terminates bots at game end / on error.
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

static FILE *lg;
static void h(int s) { fprintf(lg, "SIGNAL %d (%s)\n", s, strsignal(s)); fflush(lg); }

int main(void) {
    lg = fopen(getenv("SIGLOG") ? getenv("SIGLOG") : "/tmp/pt/sig.txt", "w");
    setvbuf(lg, NULL, _IONBF, 0);
    int sigs[] = {SIGTERM, SIGINT, SIGHUP, SIGPIPE, SIGQUIT, SIGUSR1, SIGUSR2, SIGCHLD, SIGTSTP, SIGCONT};
    for (unsigned i = 0; i < sizeof sigs / sizeof *sigs; i++) signal(sigs[i], h);
    char buf[1 << 20];
    int lines = 0, sentname = 0;
    for (;;) {
        ssize_t n = read(0, buf, sizeof buf);
        if (n < 0) { fprintf(lg, "read err\n"); continue; }
        if (n == 0) { fprintf(lg, "STDIN EOF\n"); break; }
        for (ssize_t i = 0; i < n; i++) if (buf[i] == '\n') lines++;
        if (!sentname && lines >= 3) { printf("SIG\n"); fflush(stdout); sentname = 1; continue; }
        if (sentname) { printf("\n"); fflush(stdout); }
    }
    fprintf(lg, "loop ended, sleeping 5s to observe\n");
    sleep(5);
    fprintf(lg, "normal exit\n");
    return 0;
}

