static void dump(FILE*lg,int pid,const char*label){
    char p[64]; snprintf(p,sizeof p,"/proc/%d/stat",pid);
    FILE*f=fopen(p,"r"); if(!f){fprintf(lg,"%s pid=%d <gone>\n",label,pid);return;}
    char buf[4096]; size_t n=fread(buf,1,sizeof buf-1,f); buf[n]=0; fclose(f);
