// prints name, then on turn N (env frame N) prints BAD then optionally junk, then optionally exits
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
int main(void){
    char b[1<<20]; int lines=0,sn=0; long turn=0;
    long badturn=atol(getenv("BADTURN")?getenv("BADTURN"):"2");
    const char*bad=getenv("BAD")?getenv("BAD"):"garbage";
    const char*junk=getenv("JUNK")?getenv("JUNK"):"";
    int die=getenv("DIE")!=NULL;
    long delay=atol(getenv("DELAY")?getenv("DELAY"):"0");
    for(;;){
        ssize_t k=read(0,b,sizeof b); if(k<=0) break;
        for(ssize_t i=0;i<k;i++) if(b[i]=='\n') lines++;
        if(!sn&&lines>=3){ printf("%s\n", getenv("NAME")?getenv("NAME"):"BAD"); fflush(stdout); sn=1; continue; }
        if(!sn) continue;
        turn++;
        if(turn==badturn){
            printf("%s\n", bad);
            if(*junk) printf("%s", junk);
            fflush(stdout);
            if(die){ if(delay) usleep(delay*1000); _exit(0); }
        } else { printf("\n"); fflush(stdout); }
    }
    return 0;
}
